// Some portions generated by Codex
package org.eclipse.rdf4j.sail.lmdb.evaluation.codegen;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertFalse;
import static org.junit.jupiter.api.Assertions.assertTrue;

import java.util.concurrent.atomic.AtomicBoolean;
import java.util.concurrent.atomic.AtomicInteger;
import java.util.concurrent.atomic.AtomicLong;

import org.junit.jupiter.api.Test;

class KernelCancellationOrdinaryExecutionTest {

	@Test
	void ordinaryExecutionDoesNotTurnAnArtificialHorizonIntoCancellation() {
		AtomicLong now = new AtomicLong();
		KernelCancellation cancellation = KernelCancellation.forOrdinaryExecution(null, null, null, now::get);

		now.set((Long.MAX_VALUE >> 2) + 1L);
		assertFalse(cancellation.cancelled(), "ordinary execution has no elapsed-time deadline");
	}

	@Test
	void ordinaryExecutionDoesNotReadTheClockWhilePolling() {
		AtomicInteger clockReads = new AtomicInteger();
		KernelCancellation cancellation = KernelCancellation.forOrdinaryExecution(null, null, null,
				clockReads::incrementAndGet);

		int readsAfterConstruction = clockReads.get();
		assertFalse(cancellation.cancelled());
		assertFalse(cancellation.cancelled());
		assertEquals(readsAfterConstruction, clockReads.get(),
				"ordinary polls must not read a synthetic deadline clock");
	}

	@Test
	void ordinaryExecutionStillObservesWorkerAndQuerySignalsImmediately() {
		AtomicBoolean workerCancelled = new AtomicBoolean();
		KernelCancellation worker = KernelCancellation.forOrdinaryExecution(workerCancelled::get, null, null,
				() -> 0L);
		assertFalse(worker.cancelled());
		workerCancelled.set(true);
		assertEquals(KernelCancellation.PROBE_CANCELLED, worker.cancellationReason());

		AtomicBoolean queryCancelled = new AtomicBoolean();
		KernelCancellation query = KernelCancellation.forOrdinaryExecution(null, queryCancelled::get, null,
				() -> 0L);
		assertFalse(query.cancelled());
		queryCancelled.set(true);
		assertEquals(KernelCancellation.QUERY_CANCELLED, query.cancellationReason());
	}

	@Test
	void ordinaryPeerCancellationCanUpgradeAndQueryWinsSimultaneousSignals() {
		AtomicBoolean peerCancelled = new AtomicBoolean();
		AtomicBoolean queryCancelled = new AtomicBoolean();
		KernelCancellation aggregate = KernelCancellation.forOrdinaryExecution(null, queryCancelled::get,
				peerCancelled::get, () -> 0L);

		peerCancelled.set(true);
		assertEquals(KernelCancellation.PEER_CANCELLED, aggregate.cancellationReason());
		queryCancelled.set(true);
		assertEquals(KernelCancellation.QUERY_CANCELLED, aggregate.cancellationReason());

		KernelCancellation simultaneous = KernelCancellation.forOrdinaryExecution(() -> true, () -> true, null,
				() -> 0L);
		assertEquals(KernelCancellation.QUERY_CANCELLED, simultaneous.cancellationReason());
	}

	@Test
	void explicitDeadlineConstructorRetainsExpiryAndWrapSafeComparison() {
		AtomicLong now = new AtomicLong(100L);
		KernelCancellation live = new KernelCancellation(200L, null, null, -1, null, null, now::get);
		assertFalse(live.cancelled());
		now.set(200L);
		assertTrue(live.cancelled());
		assertTrue(live.cancelled(), "deadline cancellation remains latched");

		AtomicLong wrappedNow = new AtomicLong(Long.MAX_VALUE - 2L);
		KernelCancellation wrapped = new KernelCancellation(Long.MIN_VALUE + 2L, null, null, -1, null, null,
				wrappedNow::get);
		assertFalse(wrapped.cancelled(), "a deadline just after nanoTime wrap is still in the future");
		wrappedNow.set(Long.MIN_VALUE + 2L);
		assertTrue(wrapped.cancelled());
	}
}
